package sprint

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"github.com/Antonio7098/ultraplan-go/internal/project"
	"github.com/Antonio7098/ultraplan-go/internal/workspace"
)

type EvidenceEntry struct {
	Name    string
	Path    string
	RelPath string
}

type HandbookManifest struct {
	ProjectSlug      string
	SprintSlug       string
	SprintRoot       string
	RequirementsPath string
	ProjectIndexPath string
	SprintIndexPath  string
	OutputPath       string
	Evidence         []EvidenceEntry
}

func BuildHandbookManifest(root string, sp Sprint, inputs PlanningInputs, catalog project.ProjectIndex) (HandbookManifest, []ValidationFinding) {
	index, findings := ValidateSprintIndexContent(inputs.SprintIndex, catalog)
	manifest := HandbookManifest{
		ProjectSlug:      sp.Project,
		SprintSlug:       sp.Slug,
		SprintRoot:       filepath.ToSlash(filepath.Join("projects", sp.Project, "sprints", sp.Slug)),
		RequirementsPath: ArtifactRelPath(sp, StageRequirements),
		ProjectIndexPath: filepath.ToSlash(filepath.Join("projects", sp.Project, "project-index.md")),
		SprintIndexPath:  ArtifactRelPath(sp, StageSprintIndex),
		OutputPath:       ArtifactRelPath(sp, StageTechnicalHandbook),
	}
	seen := map[string]bool{}
	for _, selected := range index.EvidenceReports {
		key := strings.ToLower(selected.Name + "\x00" + selected.Path)
		if seen[key] {
			findings = append(findings, finding("Selected Evidence Reports", selected.Name, selected.Path, "duplicate selected evidence", "same evidence report appears more than once", "Remove the duplicate selected evidence row."))
			continue
		}
		seen[key] = true
		entry, ok := catalogEvidence(catalog, selected)
		if !ok {
			continue
		}
		rel := normalizeWorkspacePath(entry.Path)
		if filepath.IsAbs(rel) || strings.HasPrefix(filepath.ToSlash(filepath.Clean(filepath.FromSlash(rel))), "../") {
			findings = append(findings, finding("Selected Evidence Reports", selected.Name, selected.Path, "unsafe evidence path", "path escapes the workspace", "Use a workspace-relative catalog path."))
			continue
		}
		full, err := workspace.ResolveInside(root, rel)
		if err != nil {
			findings = append(findings, finding("Selected Evidence Reports", selected.Name, selected.Path, "unsafe evidence path", err.Error(), "Use a workspace-relative catalog path."))
			continue
		}
		info, err := os.Stat(full)
		if err != nil {
			findings = append(findings, finding("Selected Evidence Reports", selected.Name, selected.Path, "unreadable selected evidence", err.Error(), "Ensure the selected report exists and is readable."))
			continue
		}
		if info.IsDir() || info.Size() == 0 {
			findings = append(findings, finding("Selected Evidence Reports", selected.Name, selected.Path, "invalid selected evidence file", "path is empty or a directory", "Select a non-empty Markdown evidence report."))
			continue
		}
		manifest.Evidence = append(manifest.Evidence, EvidenceEntry{Name: selected.Name, Path: selected.Path, RelPath: rel})
	}
	sort.SliceStable(manifest.Evidence, func(i, j int) bool {
		if manifest.Evidence[i].Name != manifest.Evidence[j].Name {
			return manifest.Evidence[i].Name < manifest.Evidence[j].Name
		}
		return manifest.Evidence[i].Path < manifest.Evidence[j].Path
	})
	sortSprintFindings(findings)
	return manifest, findings
}

func ValidateTechnicalHandbookContent(content string, manifest HandbookManifest) []ValidationFinding {
	var findings []ValidationFinding
	if strings.TrimSpace(content) == "" {
		return []ValidationFinding{finding("technical-handbook.md", "", "", "empty technical handbook", "file has no content", "Generate or write the required handbook sections.")}
	}
	if containsPlaceholder(content) {
		findings = append(findings, finding("technical-handbook.md", "", "", "placeholder content", "file still contains placeholder markers", "Replace placeholders with concrete handbook content."))
	}
	sections := markdownSections(content)
	required := []string{"Selected Studies And Reports", "Relevant Patterns", "Trade-Offs", "Anti-Patterns And Warnings", "Open Questions For Reasoning", "Evidence Pointers"}
	for _, section := range required {
		if strings.TrimSpace(sections[section]) == "" {
			findings = append(findings, finding(section, "", "", "missing required section", "section was not found or has no content", "Add evidence-backed handbook content for this section."))
		}
	}
	traceText := sections["Selected Studies And Reports"] + "\n" + sections["Evidence Pointers"]
	for _, evidence := range manifest.Evidence {
		if !strings.Contains(traceText, evidence.Name) && !strings.Contains(traceText, evidence.Path) && !strings.Contains(traceText, evidence.RelPath) {
			findings = append(findings, finding("Evidence Pointers", evidence.Name, evidence.Path, "missing selected evidence trace", "selected evidence is not cited in handbook evidence sections", "Cite each selected report name or selected report path."))
		}
	}
	allowed := map[string]bool{}
	for _, evidence := range manifest.Evidence {
		allowed[strings.ToLower(evidence.Name)] = true
		allowed[strings.ToLower(evidence.Path)] = true
		allowed[strings.ToLower(evidence.RelPath)] = true
	}
	for _, path := range markdownPaths(content) {
		lp := strings.ToLower(path)
		normalized := strings.ToLower(normalizeWorkspacePath(path))
		if strings.Contains(lp, "/reports/final/") && !allowed[lp] && !allowed[normalized] {
			findings = append(findings, finding("Evidence Pointers", "", path, "unselected evidence reference", "handbook cites a report that is not selected by sprint-index.md", "Use only selected evidence reports."))
		}
	}
	sortSprintFindings(findings)
	return findings
}

func catalogEvidence(catalog project.ProjectIndex, selected SelectedItem) (project.CatalogEntry, bool) {
	for _, entry := range catalog.Entries {
		if entry.Section == project.SectionAvailableEvidenceReports && strings.EqualFold(entry.Name, selected.Name) && entry.Path == selected.Path {
			return entry, true
		}
	}
	return project.CatalogEntry{}, false
}

func normalizeWorkspacePath(path string) string {
	path = strings.Trim(path, "`")
	path = filepath.ToSlash(path)
	if strings.HasPrefix(path, "ultra/") {
		path = "." + path
	}
	return strings.TrimPrefix(path, ".ultra/")
}

func markdownSections(content string) map[string]string {
	sections := map[string]string{}
	current := ""
	for _, line := range strings.Split(content, "\n") {
		trimmed := strings.TrimSpace(line)
		if strings.HasPrefix(trimmed, "## ") {
			current = strings.TrimSpace(strings.TrimPrefix(trimmed, "## "))
			sections[current] = ""
			continue
		}
		if current != "" {
			sections[current] += line + "\n"
		}
	}
	return sections
}

var mdPathPattern = regexp.MustCompile(`(?:\.ultra/)?[A-Za-z0-9._/-]+/reports/final/[A-Za-z0-9._/-]+\.md`)

func markdownPaths(content string) []string {
	matches := mdPathPattern.FindAllString(content, -1)
	out := make([]string, 0, len(matches))
	seen := map[string]bool{}
	for _, match := range matches {
		match = strings.Trim(match, "`.,);")
		if strings.HasPrefix(match, "ultra/") {
			match = "." + match
		}
		if !seen[match] {
			seen[match] = true
			out = append(out, match)
		}
	}
	sort.Strings(out)
	return out
}

func formatManifest(manifest HandbookManifest) string {
	var b strings.Builder
	fmt.Fprintf(&b, "- Project: %s\n", manifest.ProjectSlug)
	fmt.Fprintf(&b, "- Sprint: %s\n", manifest.SprintSlug)
	fmt.Fprintf(&b, "- Sprint root: %s\n", manifest.SprintRoot)
	fmt.Fprintf(&b, "- Requirements: %s\n", manifest.RequirementsPath)
	fmt.Fprintf(&b, "- Project index: %s\n", manifest.ProjectIndexPath)
	fmt.Fprintf(&b, "- Sprint index: %s\n", manifest.SprintIndexPath)
	fmt.Fprintf(&b, "- Output: %s\n", manifest.OutputPath)
	fmt.Fprintln(&b, "- Selected evidence:")
	for _, evidence := range manifest.Evidence {
		fmt.Fprintf(&b, "  - %s: %s\n", evidence.Name, evidence.Path)
	}
	return b.String()
}

package sprint

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	pruntime "github.com/Antonio7098/ultraplan-go/internal/platform/runtime"
)

const stageSessionSchemaVersion = 1

type stageSessionRecord struct {
	SessionID      string    `json:"sessionId"`
	Provider       string    `json:"provider,omitempty"`
	Model          string    `json:"model,omitempty"`
	WorkDir        string    `json:"workDir"`
	PromptChecksum string    `json:"promptChecksum,omitempty"`
	UpdatedAt      time.Time `json:"updatedAt"`
}

type stageSessionState struct {
	SchemaVersion int                           `json:"schemaVersion"`
	Sessions      map[string]stageSessionRecord `json:"sessions"`
}

func stageSessionPath(sp Sprint) string { return filepath.Join(sp.Path, ".stage-sessions.json") }

func loadStageSessions(sp Sprint) (stageSessionState, error) {
	path := stageSessionPath(sp)
	data, err := os.ReadFile(path)
	if errors.Is(err, os.ErrNotExist) {
		return stageSessionState{SchemaVersion: stageSessionSchemaVersion, Sessions: map[string]stageSessionRecord{}}, nil
	}
	if err != nil {
		return stageSessionState{}, err
	}
	var state stageSessionState
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&state); err != nil {
		return stageSessionState{}, fmt.Errorf("decode stage sessions: %w", err)
	}
	var trailing any
	if err := dec.Decode(&trailing); !errors.Is(err, io.EOF) {
		return stageSessionState{}, fmt.Errorf("decode stage sessions: trailing JSON")
	}
	if state.SchemaVersion != stageSessionSchemaVersion || state.Sessions == nil {
		return stageSessionState{}, fmt.Errorf("unsupported stage session state")
	}
	return state, nil
}

func saveStageSessions(sp Sprint, state stageSessionState) error {
	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return err
	}
	data = append(data, '\n')
	path := stageSessionPath(sp)
	tmp, err := os.CreateTemp(sp.Path, ".stage-sessions.*.tmp")
	if err != nil {
		return err
	}
	tmpPath := tmp.Name()
	defer os.Remove(tmpPath)
	if _, err = tmp.Write(data); err == nil {
		err = tmp.Chmod(0o600)
	}
	if closeErr := tmp.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return err
	}
	return os.Rename(tmpPath, path)
}

func stageSessionCompatible(record stageSessionRecord, req pruntime.Request) bool {
	// Prompt checksums are retained for diagnostics only. Exact prompt matching
	// would make interrupted-session recovery brittle after harmless artifact
	// edits; the continuation explicitly tells the agent to reread current state.
	return record.SessionID != "" && record.Provider == req.Provider && record.Model == req.Model && record.WorkDir == req.WorkDir
}

func stageSessionKey(stage PlanningStage, req pruntime.Request) string {
	parts := []string{string(stage)}
	for _, dimension := range []string{"task", "coverage", "area"} {
		parts = append(parts, strings.TrimSpace(req.Metadata[dimension]))
	}
	if parts[1] == "" && parts[2] == "" && parts[3] == "" {
		return parts[0]
	}
	return strings.Join(parts, ":")
}

func (s Service) startPlanningStageRun(ctx context.Context, sp Sprint, stage PlanningStage, req pruntime.Request) (pruntime.Result, error) {
	key := stageSessionKey(stage, req)
	originalPrompt := req.Prompt
	continuing := false
	state, loadErr := loadStageSessions(sp)
	if loadErr == nil {
		if record, ok := state.Sessions[key]; ok && stageSessionCompatible(record, req) {
			req.SessionID = record.SessionID
			req.SessionAction = "continue"
			req.Prompt = insertStageContinuation(req.Prompt, "Continue the interrupted UltraPlan stage from the existing session. Re-read the current stage prompt and filesystem state, then finish only the requested stage.")
			continuing = true
		}
	}
	previousOnEvent := req.OnEvent
	var mu sync.Mutex
	lastSession := req.SessionID
	persist := func(sessionID string) {
		if strings.TrimSpace(sessionID) == "" {
			return
		}
		mu.Lock()
		defer mu.Unlock()
		if sessionID == lastSession {
			return
		}
		lastSession = sessionID
		current, err := loadStageSessions(sp)
		if err != nil {
			return
		}
		current.Sessions[key] = stageSessionRecord{SessionID: sessionID, Provider: req.Provider, Model: req.Model, WorkDir: req.WorkDir, PromptChecksum: req.PromptRef.Checksum, UpdatedAt: s.now().UTC()}
		_ = saveStageSessions(sp, current)
	}
	req.OnEvent = func(event pruntime.Event) {
		if previousOnEvent != nil {
			previousOnEvent(event)
		}
		persist(event.SessionID)
	}
	result, err := s.startSprintRuntime(ctx, sp, stage, req)
	persist(result.SessionID)
	if continuing && planningSessionNotFound(result, err) && ctx.Err() == nil {
		_ = clearPlanningStageSessionKey(sp, key)
		lastSession = ""
		req.SessionID = ""
		req.SessionAction = "fresh"
		req.Prompt = originalPrompt
		result, err = s.startSprintRuntime(ctx, sp, stage, req)
		persist(result.SessionID)
	}
	return result, err
}

func planningSessionNotFound(result pruntime.Result, err error) bool {
	var details []string
	if err != nil {
		details = append(details, err.Error())
	}
	details = append(details, result.TerminalOutput)
	if result.Error != nil {
		details = append(details, result.Error.UserDetail, result.Error.DebugDetail)
	}
	for _, attempt := range result.Attempts {
		details = append(details, attempt.ErrorDetail)
	}
	return strings.Contains(strings.ToLower(strings.Join(details, "\n")), "session not found")
}

func insertStageContinuation(prompt, instruction string) string {
	boundary := strings.Index(prompt, sharedPromptStageBoundary)
	if boundary < 0 {
		return instruction + "\n\n" + prompt
	}
	boundary += len(sharedPromptStageBoundary)
	return prompt[:boundary] + instruction + "\n\n" + prompt[boundary:]
}

func clearPlanningStageSession(sp Sprint, stage PlanningStage) error {
	state, err := loadStageSessions(sp)
	if err != nil {
		return err
	}
	found := false
	for key := range state.Sessions {
		if key == string(stage) || strings.HasPrefix(key, string(stage)+":") {
			delete(state.Sessions, key)
			found = true
		}
	}
	if !found {
		return nil
	}
	return saveOrRemoveStageSessions(sp, state)
}

func clearPlanningStageSessionKey(sp Sprint, key string) error {
	state, err := loadStageSessions(sp)
	if err != nil {
		return err
	}
	if _, ok := state.Sessions[key]; !ok {
		return nil
	}
	delete(state.Sessions, key)
	return saveOrRemoveStageSessions(sp, state)
}

func saveOrRemoveStageSessions(sp Sprint, state stageSessionState) error {
	if len(state.Sessions) == 0 {
		if err := os.Remove(stageSessionPath(sp)); err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
		return nil
	}
	return saveStageSessions(sp, state)
}

func (s Service) cleanupPlanningStageSession(ctx context.Context, sp Sprint, stage PlanningStage, sessionID string) error {
	if err := s.deleteCompletedSession(ctx, sessionID); err != nil {
		return err
	}
	return clearPlanningStageSession(sp, stage)
}

func (s Service) cleanupPlanningStageSessions(ctx context.Context, sp Sprint, stage PlanningStage, result pruntime.Result) error {
	if err := s.deleteCompletedSessions(ctx, result); err != nil {
		return err
	}
	return clearPlanningStageSession(sp, stage)
}

